package embedding

import (
	"encoding/json"
	"flag"
	"math"
	"os"
	"sort"
	"testing"
)

// The opt-in input is generated by the upstream model runtime in an isolated
// container. This development probe measures quantization distortion, not
// retrieval relevance, held-out quality or release suitability.
var referenceVectors = flag.String("embedding-reference-vectors", "", "development-only float vectors from the reference model")

func TestReferenceQuantizationProbe(t *testing.T) {
	if *referenceVectors == "" {
		t.Skip("development reference vectors not supplied")
	}
	data, err := os.ReadFile(*referenceVectors)
	if err != nil {
		t.Fatal(err)
	}
	var input struct {
		IDs     []string    `json:"ids"`
		Vectors [][]float64 `json:"vectors"`
	}
	if err := json.Unmarshal(data, &input); err != nil {
		t.Fatal(err)
	}
	expected := []string{"dev-build-01", "dev-build-02", "dev-cache-01", "dev-cache-02", "dev-hostile-01", "dev-exact", "dev-paraphrase", "dev-noanswer", "dev-adversarial"}
	if len(input.IDs) != len(expected) || len(input.Vectors) != len(expected) {
		t.Fatal("unexpected development dataset")
	}
	encoded := make([][Dimensions]byte, len(expected))
	for i, id := range expected {
		if input.IDs[i] != id {
			t.Fatalf("unexpected id %d", i)
		}
		encoded[i], err = EncodeUnit(input.Vectors[i])
		if err != nil {
			t.Fatalf("encode %s: %v", id, err)
		}
	}
	type result struct {
		id    string
		score float64
	}
	sortRank := func(x []result) {
		sort.Slice(x, func(i, j int) bool {
			if x[i].score != x[j].score {
				return x[i].score > x[j].score
			}
			return x[i].id < x[j].id
		})
	}
	var maxError float64
	sameOrder := 0
	for q := 5; q < len(expected); q++ {
		var floats, quantized []result
		for d := 0; d < 5; d++ {
			var dot, qa, da float64
			for i, x := range input.Vectors[q] {
				y := input.Vectors[d][i]
				dot += x * y
				qa += x * x
				da += y * y
			}
			if qa == 0 || da == 0 {
				t.Fatal("zero float vector")
			}
			original := dot / math.Sqrt(qa*da)
			approx, err := Cosine(encoded[q], encoded[d])
			if err != nil {
				t.Fatal(err)
			}
			if delta := math.Abs(original - approx); delta > maxError {
				maxError = delta
			}
			floats = append(floats, result{expected[d], original})
			quantized = append(quantized, result{expected[d], approx})
		}
		sortRank(floats)
		sortRank(quantized)
		same := true
		for i := range floats {
			if floats[i].id != quantized[i].id {
				same = false
			}
		}
		if same {
			sameOrder++
		}
		t.Logf("query=%s float_top=%s quantized_top=%s same_full_order=%t", expected[q], floats[0].id, quantized[0].id, same)
	}
	t.Logf("development_only queries=%d source_vectors=5 same_full_order=%d max_absolute_cosine_error=%.8f", len(expected)-5, sameOrder, maxError)
}
